1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import type { ReactNode } from "react";
5	import { Button, IconButton } from "./Button";
6	import { Input } from "./Field";
7	
8	/* Built on the native <dialog>, not a portal + div. showModal() gives the
9	   focus trap, the inert background, the top-layer stacking and Escape for
10	   free — all four of which are what hand-rolled modals get wrong, and all
11	   four of which are the accessible behaviour rather than the look. */
12	export function Modal({
13	  open,
14	  onClose,
15	  title,
16	  description,
17	  children,
18	  footer,
19	  size = "md",
20	}: {
21	  open: boolean;
22	  onClose: () => void;
23	  title: string;
24	  description?: ReactNode;
25	  children?: ReactNode;
26	  footer?: ReactNode;
27	  size?: "sm" | "md" | "lg";
28	}) {
29	  const ref = useRef<HTMLDialogElement>(null);
30	
31	  useEffect(() => {
32	    const el = ref.current;
33	    if (!el) return;
34	    // Guard both directions: calling showModal() on an already-open dialog
35	    // throws InvalidStateError, and close() on a closed one fires a spurious
36	    // cancel/close event that would call onClose in a loop.
37	    if (open && !el.open) el.showModal();
38	    if (!open && el.open) el.close();
39	  }, [open]);
40	
41	  const width = { sm: "max-w-sm", md: "max-w-lg", lg: "max-w-2xl" }[size];
42	
43	  return (
44	    <dialog
45	      ref={ref}
46	      // `cancel` is Escape. Prevented and routed through onClose so the parent
47	      // stays the single owner of `open` — otherwise the dialog closes itself
48	      // and React re-opens it on the next render.
49	      onCancel={(e) => {
50	        e.preventDefault();
51	        onClose();
52	      }}
53	      onClose={onClose}
54	      // Clicking the backdrop targets the dialog element itself; clicking
55	      // anything inside targets a descendant. That distinction is the whole
56	      // click-outside implementation.
57	      onClick={(e) => {
58	        if (e.target === ref.current) onClose();
59	      }}
60	      className={`m-auto w-[calc(100vw-2rem)] ${width} rounded-xl border border-line-mid bg-surface p-0 text-ink shadow-e3 backdrop:bg-black/45 backdrop:backdrop-blur-sm`}
61	    >
62	      <div className="flex items-start justify-between gap-4 px-5 pt-5">
63	        <div className="min-w-0">
64	          <h2 className="k-h2 text-ink">{title}</h2>
65	          {description != null && (
66	            <p className="mt-1 text-[0.8125rem] leading-relaxed text-ink-2">{description}</p>
67	          )}
68	        </div>
69	        <IconButton label="Close" size="sm" onClick={onClose}>
70	          <svg viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
71	            <path d="m6 6 12 12M18 6 6 18" />
72	          </svg>
73	        </IconButton>
74	      </div>
75	      {children != null && <div className="px-5 py-4 text-sm text-ink-2">{children}</div>}
76	      {footer != null && (
77	        <div className="flex justify-end gap-2 border-t border-hair bg-surface-2/50 px-5 py-3.5">
78	          {footer}
79	        </div>
80	      )}
81	    </dialog>
82	  );
83	}
84	
85	/** Confirmation for a destructive action. The label of the confirm button is
86	    the verb, never "OK" — the customer should be able to read the button
87	    alone and know what is about to happen.
88	
89	    `requireText` restores the type-the-name gate. It exists because the old
90	    hand-rolled delete dialog had one for published sites and the first pass of
91	    this redesign dropped it: deleting a published site takes a live address
92	    offline immediately and the slug returns to the pool, so it is genuinely
93	    unrecoverable, and a two-click confirm is not enough friction for that.
94	    Use it ONLY where the consequence is irreversible AND public — asking
95	    someone to type a name to dismiss a draft is theatre, and theatre trains
96	    people to type without reading. */
97	export function ConfirmModal({
98	  open,
99	  onClose,
100	  onConfirm,
101	  title,
102	  body,
103	  confirmLabel,
104	  busy = false,
105	  requireText,
106	  requireTextLabel,
107	}: {
108	  open: boolean;
109	  onClose: () => void;
110	  onConfirm: () => void;
111	  title: string;
112	  body: ReactNode;
113	  confirmLabel: string;
114	  busy?: boolean;
115	  /** Exact string the customer must type before confirm enables. */
116	  requireText?: string;
117	  /** Defaults to naming what they are typing. */
118	  requireTextLabel?: string;
119	}) {
120	  const [typed, setTyped] = useState("");
121	
122	  // Trim only — never lowercase. Matching case-insensitively would accept a
123	  // near-miss, and the whole point is that they read the name character by
124	  // character before the button lights up.
125	  const satisfied = requireText == null || typed.trim() === requireText;
126	
127	  const close = () => {
128	    setTyped("");
129	    onClose();
130	  };
131	
132	  return (
133	    <Modal
134	      open={open}
135	      onClose={close}
136	      title={title}
137	      size="sm"
138	      footer={
139	        <>
140	          <Button variant="ghost" size="sm" onClick={close} disabled={busy}>
141	            Cancel
142	          </Button>
143	          <Button
144	            variant="danger"
145	            size="sm"
146	            onClick={onConfirm}
147	            loading={busy}
148	            disabled={!satisfied}
149	          >
150	            {confirmLabel}
151	          </Button>
152	        </>
153	      }
154	    >
155	      {body}
156	      {requireText != null && (
157	        <div className="mt-4">
158	          <Input
159	            label={requireTextLabel ?? `Type ${requireText} to confirm`}
160	            value={typed}
161	            onChange={(e) => setTyped(e.target.value)}
162	            autoComplete="off"
163	            spellCheck={false}
164	            disabled={busy}
165	          />
166	        </div>
167	      )}
168	    </Modal>
169	  );
170	}
