3	import { useId } from "react";
4	import type { ComponentProps, ReactNode } from "react";
5	
6	const CONTROL =
7	  "w-full rounded-md border border-line-mid bg-surface px-3 text-sm text-ink placeholder:text-ink-3 " +
8	  "transition-[border-color,box-shadow] duration-[var(--t-1)] " +
9	  "focus:border-brand focus:outline-none focus:ring-4 focus:ring-[var(--brand-tint)] " +
10	  "disabled:cursor-not-allowed disabled:bg-surface-2 disabled:text-ink-3";
11	
12	/* Label, hint and error are part of the control, not siblings a caller has to
13	   remember to wire up: `useId` links them via aria-describedby/aria-invalid
14	   automatically, which is the half that always got skipped when each page
15	   hand-rolled its own form markup. */
16	function Wrapper({
17	  label,
18	  hint,
19	  error,
20	  required,
21	  id,
22	  hintId,
23	  errorId,
24	  children,
25	}: {
26	  label?: ReactNode;
27	  hint?: ReactNode;
28	  error?: ReactNode;
29	  required?: boolean;
30	  id: string;
31	  hintId: string;
32	  errorId: string;
33	  children: ReactNode;
34	}) {
35	  return (
36	    <div className="flex flex-col gap-1.5">
37	      {label != null && (
38	        <label htmlFor={id} className="text-[0.8125rem] font-medium text-ink">
39	          {label}
40	          {required && (
41	            <span className="ml-1 text-danger" aria-hidden>
42	              *
43	            </span>
44	          )}
45	        </label>
46	      )}
47	      {children}
48	      {/* Error replaces the hint rather than stacking under it — two lines of
49	          advice at the moment something went wrong is one too many. */}
50	      {error != null ? (
51	        <p id={errorId} className="text-xs text-danger">
52	          {error}
53	        </p>
54	      ) : hint != null ? (
55	        <p id={hintId} className="text-xs text-ink-3">
56	          {hint}
57	        </p>
58	      ) : null}
59	    </div>
60	  );
61	}
62	
63	type Shared = { label?: ReactNode; hint?: ReactNode; error?: ReactNode };
64	
65	export function Input({ label, hint, error, className = "", ...rest }: Shared & ComponentProps<"input">) {
66	  const auto = useId();
67	  const id = rest.id ?? auto;
68	  return (
69	    <Wrapper
70	      label={label}
71	      hint={hint}
72	      error={error}
73	      required={rest.required}
74	      id={id}
75	      hintId={`${auto}-h`}
76	      errorId={`${auto}-e`}
77	    >
78	      <input
79	        {...rest}
80	        id={id}
81	        aria-invalid={error != null || undefined}
82	        aria-describedby={error != null ? `${auto}-e` : hint != null ? `${auto}-h` : undefined}
83	        className={`${CONTROL} h-9.5 ${error != null ? "border-danger" : ""} ${className}`}
84	      />
85	    </Wrapper>
86	  );
87	}
88	
89	export function Textarea({
90	  label,
91	  hint,
92	  error,
93	  className = "",
94	  ...rest
95	}: Shared & ComponentProps<"textarea">) {
96	  const auto = useId();
97	  const id = rest.id ?? auto;
98	  return (
99	    <Wrapper
100	      label={label}
101	      hint={hint}
102	      error={error}
103	      required={rest.required}
104	      id={id}
105	      hintId={`${auto}-h`}
106	      errorId={`${auto}-e`}
107	    >
108	      <textarea
109	        {...rest}
110	        id={id}
111	        aria-invalid={error != null || undefined}
112	        aria-describedby={error != null ? `${auto}-e` : hint != null ? `${auto}-h` : undefined}
113	        className={`${CONTROL} resize-y py-2.5 leading-relaxed ${error != null ? "border-danger" : ""} ${className}`}
114	      />
115	    </Wrapper>
116	  );
117	}
118	
119	export function Select({
120	  label,
121	  hint,
122	  error,
123	  className = "",
124	  children,
125	  ...rest
126	}: Shared & ComponentProps<"select">) {
127	  const auto = useId();
128	  const id = rest.id ?? auto;
129	  return (
130	    <Wrapper
131	      label={label}
132	      hint={hint}
133	      error={error}
134	      required={rest.required}
135	      id={id}
136	      hintId={`${auto}-h`}
137	      errorId={`${auto}-e`}
138	    >
139	      <select {...rest} id={id} className={`${CONTROL} h-9.5 cursor-pointer pr-8 ${className}`}>
140	        {children}
141	      </select>
142	    </Wrapper>
143	  );
144	}
145	
146	/** Search input with the magnifier baked in and a real `type="search"`, so
147	    the browser's own clear affordance and Escape-to-clear both work. */
148	export function SearchInput({ className = "", ...rest }: ComponentProps<"input">) {
149	  return (
150	    <div className={`relative ${className}`}>
151	      <svg
152	        viewBox="0 0 24 24"
153	        aria-hidden
154	        className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-ink-3"
155	        fill="none"
156	        stroke="currentColor"
157	        strokeWidth="2"
158	        strokeLinecap="round"
159	      >
160	        <circle cx="11" cy="11" r="7" />
161	        <path d="m20 20-3.6-3.6" />
162	      </svg>
163	      <input {...rest} type="search" className={`${CONTROL} h-9.5 pl-9`} />
164	    </div>
165	  );
166	}
