1	import type { ReactNode } from "react";
2	
3	export type Tone = "neutral" | "brand" | "ok" | "warn" | "danger" | "info";
4	
5	const TONE: Record<Tone, string> = {
6	  neutral: "bg-surface-2 text-ink-2 border-hair",
7	  brand: "bg-brand-tint text-brand-ink border-transparent dark:text-brand",
8	  ok: "bg-ok-tint text-ok border-transparent",
9	  warn: "bg-warn-tint text-warn border-transparent",
10	  danger: "bg-danger-tint text-danger border-transparent",
11	  info: "bg-info-tint text-info border-transparent",
12	};
13	
14	const DOT: Record<Tone, string> = {
15	  neutral: "bg-ink-3",
16	  brand: "bg-brand",
17	  ok: "bg-ok",
18	  warn: "bg-warn",
19	  danger: "bg-danger",
20	  info: "bg-info",
21	};
22	
23	/* Status has to survive being printed in greyscale and being looked at by
24	   someone who cannot separate the hues, so `dot` is not decoration — it is
25	   the second channel. Anything conveying live state should set it, and
26	   `pulse` marks the one state that is still changing. */
27	export function Badge({
28	  tone = "neutral",
29	  dot = false,
30	  pulse = false,
31	  children,
32	  className = "",
33	}: {
34	  tone?: Tone;
35	  dot?: boolean;
36	  pulse?: boolean;
37	  children: ReactNode;
38	  className?: string;
39	}) {
40	  return (
41	    <span
42	      className={`inline-flex items-center gap-1.5 rounded-full border px-2 py-0.5 text-[0.6875rem] font-medium whitespace-nowrap ${TONE[tone]} ${className}`}
43	    >
44	      {dot && (
45	        <span className="relative flex size-1.5">
46	          {pulse && (
47	            <span
48	              className={`absolute inline-flex size-full animate-ping rounded-full opacity-75 ${DOT[tone]}`}
49	            />
50	          )}
51	          <span className={`relative inline-flex size-1.5 rounded-full ${DOT[tone]}`} />
52	        </span>
53	      )}
54	      {children}
55	    </span>
56	  );
57	}
