102	/**
103	 * A closed organic blob: a circle whose radius is modulated by two sine terms.
104	 * `wobble` 0 gives a plain ellipse; 0.05-0.2 is the band that still reads as a
105	 * deliberate shape rather than a splat.
106	 */
107	function blobPath(cx: number, cy: number, r: number, phase: number, wobble = 0.11, squash = 1, points = 8): string {
108	  const pts: Pt[] = [];
109	  for (let i = 0; i < points; i++) {
110	    const a = (i / points) * Math.PI * 2;
111	    const rr = r * (1 + wobble * Math.sin(3 * a + phase) + wobble * 0.55 * Math.sin(5 * a - phase));
112	    pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr * squash]);
113	  }
114	  return closedSpline(pts);
115	}
