384	export type BackdropOptions = {
385	  /** Change this to get a different arrangement of the same idea. Default: the id. */
386	  seed?: string;
387	  /**
388	   * Palette, cycled per layer. Omit for `currentColor`, which is the default
389	   * for a reason: the backdrop then tints itself from the section's text colour
390	   * and works on light and dark without a second variant.
391	   */
392	  colors?: string[];
393	  className?: string;
394	  title?: string;
395	};
