397	/**
398	 * A full-bleed `<svg>` hero backdrop. Absolutely position it inside a
399	 * `relative overflow-hidden` section, behind the content.
400	 */
401	export function backdropSvg(id: string, opts: BackdropOptions = {}): string | null {
402	  const def = BACKDROP_BY_ID.get(id);
403	  if (!def) return null;
404	  const seed = opts.seed ?? id;
405	  const palette = opts.colors?.length ? opts.colors : ["currentColor"];
406	  const ink: Ink = (layer, opacity, stroked) => {
407	    const c = palette[layer % palette.length];
408	    return stroked ? ` fill="none" stroke="${c}" opacity="${opacity}"` : ` fill="${c}" opacity="${opacity}"`;
409	  };
410	  // Gradient ids are document-global, so two backdrops on one page would
411	  // collide on a fixed id. Derived from the seed, so it is still deterministic.
412	  const uid = `kb${hash32(`${id}${seed}`).toString(36)}`;
413	  const cls = `${opts.className ? `${opts.className} ` : ""}h-full w-full`;
414	  return (
415	    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${BACKDROP_VIEWBOX}" preserveAspectRatio="xMidYMid slice"` +
416	    ` width="100%" height="100%"${label(opts.title)} class="${cls}">${def.build(rng(seed), ink, uid)}</svg>`
417	  );
418	}
