(async () => {
  const figs = [...document.querySelectorAll('figure')];
  const sigs = [];
  for (const f of figs) {
    const id = f.querySelector('figcaption').textContent;
    const svg = f.querySelector('.cover svg').cloneNode(true);
    svg.setAttribute('width', '320'); svg.setAttribute('height', '180');
    const url = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(new XMLSerializer().serializeToString(svg));
    const img = new Image();
    await new Promise((res, rej) => { img.onload = res; img.onerror = () => rej(new Error('load fail ' + id)); img.src = url; });
    const c = document.createElement('canvas'); c.width = 32; c.height = 18;
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0, 32, 18);
    const d = ctx.getImageData(0, 0, 32, 18).data;
    const bits = [];
    let sum = 0; const lum = [];
    for (let i = 0; i < d.length; i += 4) { const l = 0.299*d[i]+0.587*d[i+1]+0.114*d[i+2]; lum.push(l); sum += l; }
    const mean = sum / lum.length;
    for (const l of lum) bits.push(l > mean ? 1 : 0);
    sigs.push({ id, bits, mean: Math.round(mean) });
  }
  // pairwise hamming distance over 576 cells
  let minPair = { d: 1e9 };
  const dists = [];
  for (let i = 0; i < sigs.length; i++) for (let j = i+1; j < sigs.length; j++) {
    let dd = 0; for (let k = 0; k < sigs[i].bits.length; k++) if (sigs[i].bits[k] !== sigs[j].bits[k]) dd++;
    dists.push(dd);
    if (dd < minPair.d) minPair = { d: dd, a: sigs[i].id, b: sigs[j].id };
  }
  dists.sort((a,b)=>a-b);
  return { covers: sigs.length, closestPair: minPair, medianDistance: dists[Math.floor(dists.length/2)], maxDistance: dists[dists.length-1], means: sigs.map(s=>s.id+':'+s.mean).join(' ') };
})()

