    ctx.drawImage(img,0,0,160,90);
    const d = ctx.getImageData(0,0,160,90).data;
    const lum = new Float32Array(160*90);
    for (let i=0,k=0;i<d.length;i+=4,k++) lum[k]=0.299*d[i]+0.587*d[i+1]+0.114*d[i+2];
    sigs.push({id,lum});
  }
  let worst={mae:1e9};
  const all=[];
  for(let i=0;i<sigs.length;i++)for(let j=i+1;j<sigs.length;j++){
    let s=0; for(let k=0;k<sigs[i].lum.length;k++) s+=Math.abs(sigs[i].lum[k]-sigs[j].lum[k]);
    const mae=s/sigs[i].lum.length;
    all.push({mae:+mae.toFixed(1),a:sigs[i].id,b:sigs[j].id});
    if(mae<worst.mae) worst={mae:+mae.toFixed(1),a:sigs[i].id,b:sigs[j].id};
  }
  all.sort((x,y)=>x.mae-y.mae);
  return { pairs: all.length, closest: all.slice(0,6), median: all[Math.floor(all.length/2)].mae, note:'MAE of 0-255 luminance, layout only (gradient replaced by flat grey)' };
})()

