(async () => {
  const figs=[...document.querySelectorAll('figure')]; const sigs=[];
  for (const f of figs){
    const id=f.querySelector('figcaption').textContent;
    const svg=f.querySelector('.cover svg').cloneNode(true);
    svg.setAttribute('width','320'); svg.setAttribute('height','180');
    const url='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(svg));
    const img=new Image(); await new Promise((r,j)=>{img.onload=r;img.onerror=()=>j(new Error(id));img.src=url;});
    const c=document.createElement('canvas'); c.width=160;c.height=90; const ctx=c.getContext('2d');
    ctx.fillStyle='#888';ctx.fillRect(0,0,160,90); ctx.drawImage(img,0,0,160,90);
    const d=ctx.getImageData(0,0,160,90).data; const lum=new Float32Array(160*90);
    for(let i=0,k=0;i<d.length;i+=4,k++) lum[k]=0.299*d[i]+0.587*d[i+1]+0.114*d[i+2];
    sigs.push({id,lum});
  }
  const all=[];
  for(let i=0;i<sigs.length;i++)for(let j=i+1;j<sigs.length;j++){
    let s=0; for(let k=0;k<sigs[i].lum.length;k++) s+=Math.abs(sigs[i].lum[k]-sigs[j].lum[k]);
    all.push({mae:+(s/sigs[i].lum.length).toFixed(1),a:sigs[i].id,b:sigs[j].id});
  }
  all.sort((x,y)=>x.mae-y.mae);
  return { closest: all.slice(0,5), median: all[Math.floor(all.length/2)].mae };
})()

