input.text:
(async () => {
  // Composite each cover the way it really renders: CSS gradient, then the
  // pattern layer, then the SVG. Then compare in colour, not just luminance.
  const figs=[...document.querySelectorAll('figure')]; const sigs=[];
  for (const f of figs){
    const id=f.querySelector('figcaption').textContent;
    const cover=f.querySelector('.cover');
    const grad=getComputedStyle(cover).backgroundImage;
    const svg=f.querySelector('.cover svg').cloneNode(true);
    svg.setAttribute('width','320'); svg.setAttribute('height','180');
    const url='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(svg));
    const img=new Image(); await new Promise((r,j)=>{img.onload=r;img.onerror=()=>j(new Error(id));img.src=url;});
    // approximate the gradient with its first colour stop
    const stop=grad.match(/rgb\((\d+), (\d+), (\d+)\)/);
    const c=document.createElement('canvas'); c.width=160;c.height=90; const ctx=c.getContext('2d');
    ctx.fillStyle=stop?`rgb(${stop[1]},${stop[2]},${stop[3]})`:'#888'; ctx.fillRect(0,0,160,90);
    ctx.drawImage(img,0,0,160,90);
    const d=ctx.getImageData(0,0,160,90).data;
    sigs.push({id,d});
  }
  const all=[];
  for(let i=0;i<sigs.length;i++)for(let j=i+1;j<sigs.length;j++){
    let s=0,n=0; const A=sigs[i].d,B=sigs[j].d;
    for(let k=0;k<A.length;k+=4){ s+=Math.abs(A[k]-B[k])+Math.abs(A[k+1]-B[k+1])+Math.abs(A[k+2]-B[k+2]); n+=3; }
    all.push({mae:+(s/n).toFixed(1),a:sigs[i].id,b:sigs[j].id});
  }
  all.sort((x,y)=>x.mae-y.mae);
  return { closest: all.slice(0,6), median: all[Math.floor(all.length/2)].mae, max: all[all.length-1] };
})()

