  const out = [];
  document.querySelectorAll('figure').forEach(f => {
    const id = f.querySelector('figcaption').textContent;
    const svg = f.querySelector('.cover svg');
    const nested = svg.querySelector('svg');
    const icons = [...svg.querySelectorAll('g[transform^="translate"]')];
    out.push({
      id,
      backdropShapes: nested ? nested.children.length : 0,
      iconGroups: icons.length,
      iconChildren: icons.reduce((n, g) => n + g.querySelectorAll('path,circle,rect,line,polyline').length, 0),
      defs: svg.querySelectorAll('linearGradient,clipPath').length,
      total: svg.querySelectorAll('*').length
    });
  });
  return out.map(o => `${o.id.padEnd(20)} backdrop=${String(o.backdropShapes).padEnd(3)} iconGroups=${o.iconGroups} iconShapes=${String(o.iconChildren).padEnd(3)} defs=${o.defs} nodes=${o.total}`);
})()
